    snake.y += snake.dy * GRID_SIZE;

    // Check collisions
    // Update food if eaten
    // Check game over conditions
}

void renderGame() {
    SDL_RenderClear(renderer);

    // Render background
    SDL_RenderCopy(renderer, backgroundTexture, NULL, NULL);

    // Render food
    SDL_Rect foodRect = {food.x, food.y, GRID_SIZE, GRID_SIZE};
